import {motionModels} from './motion-models.js?v=0.19.0';
// A short reading guide for every existing rendered model.
export const modelHelp={
 ...Object.fromEntries(Object.entries(motionModels).map(([key,model])=>[key,model.caption])),
 units:'Read the ruler in metres, then compare the centimetre value. Changing units does not change the length.',
 scale:'The exponent is the small raised number. Raise it by one and the length is ten times as large. Both readings show the same length.',
 relationship:'The line shows how distance builds up. A faster speed makes the line steeper.',
 vector:'The dashed route goes across, then up. The solid arrow joins the same start and finish. Its length is the displacement size.',
 slope:'Read time across and position up. A steeper line means faster motion. A downward line means the object is moving toward smaller position numbers.',
 area:'Each shaded rectangle is one part of the trip. Read time across and velocity up. Add areas above zero and subtract areas below it to find where the trip ends.',
 uncertainty:'The middle mark is the best estimate. The band shows how far the stated uncertainty reaches on either side.',
 radian:'The straight radius runs from the centre to the edge. The thick curved arc follows the edge. One radian makes these two lengths equal.',
 trig:'The solid line is a two-metre arrow. Its horizontal part is two times cosine. Its vertical part is two times sine. The dashed lines show both parts.',
 derivative:'The curved line shows each input and its output. The short straight line shows how fast the output is changing at the marked input.',
 integral:'Read time across and velocity up. The shaded triangle gives the change in position. At three seconds its area is nine metres.',
 complex:'Move across for the real part, then up or down for the imaginary part. The distance from zero to that point is the size of the complex number.',
 matrix:'The thick input and thin output lines start at zero. This matrix doubles the horizontal part and keeps the vertical part.',
 motion:'Read time across and position up. The line begins at the starting position, which can be left of zero.',
 acceleration:'This is a velocity graph. Its slope is acceleration. Crossing zero means stopping for a moment before reversing direction.',
 projectile:'Play the launch to follow the ball from the shelf to the floor. The small dots mark equal times. Gravity changes the up-and-down speed. The sideways speed stays steady. The axes adjust when you change the launch.',
 force:'The arrows are forces on one cart. Subtract the leftward force from the rightward force, then divide by mass to get acceleration.',
 efield:'Each source charge pushes a tiny positive test charge away or pulls it closer. At the middle, the pushes from two equal positive charges cancel. Move the observer to compare them.',
 rc:'Play the graph to follow the capacitor voltage. The dot marks the time. The clock uses milliseconds. One thousand milliseconds make one second.',
 magnetic:'The green arrow shows the starting velocity. The force points toward the centre of the dashed circle. Change the sign of the charge to bend the path the other way. Read the size of the orbit below.',
 damped:'The dot follows the spring on the solid position graph. The two dashed lines bound its swings. The starting limit is 10 cm. After 5 seconds the limit is about 3.68 cm.',
 wavefield:'Play the wave and follow the gold point. Its horizontal place stays fixed as it moves up and down. In a travelling wave the crests move across. In a standing wave the places that stay at zero never move.',
 slit:'The centre is bright and the dips are dark. Height is intensity divided by centre intensity. A narrower slit spreads the pattern over wider angles.',
 'gas-isotherm':'Read volume across and pressure up. Each curve keeps amount and temperature fixed.',
 'thin-lens-image':'The lens is at zero. The object is on its left. A mark pointing down means the image is upside down.',
 'moving-clock':'The carried clock measures its own elapsed time, called proper time. The graph shows the laboratory time for that same interval at different speeds.',
 'decay-expectation':'The curve is an average expected count. Half remain after each half-life.',
 'signal-yield':'Read the bars in order: produced, chosen decay, then selected by the detector.',
 'fermi-occupation':'The curve gives the chance that an electron state is filled. The energy marked zero on this graph is the chemical potential. The chance there is one half.',
 'relative-starlight':'Flux is received power per area. The curve shows how the same source looks dimmer farther away.',
 'hr-diagram-summary':'Higher means greater total light output. Left means hotter. These broad star families are a guide, not measured dots. At equal temperature, a larger star sits higher.',
 'band-occupancy-diagram':'Read energy upward. The lower band is filled and the upper band is empty in this starting case. The 2 eV gap separates allowed bands; it does not count their electrons.',
 qwell:'This model combines two waves in a box. Change their relative phase to change where they add or cancel. Height shows how likely a position is per unit of length. The area over a region gives its chance. The dot marks the point one quarter of the way across the box.',
 qgaussian:'Play the model and watch the bell spread. The centre stays in place. A wider range of positions shares the same total chance.',
 qbarrier:'The curve gives the fraction of incoming probability flow that passes through the barrier. Height 1 means full transmission; it does not show a crossing time or path.',
 qradial:'The curve groups results by distance from the centre. Near its peak, a thin shell is more likely to contain the electron than another shell of the same thickness. The number below gives the chance anywhere inside the selected distance.',
 q2spin:'This graph shows measurement chances. The preparation sets the state; the analyzer sets the direction measured. It is not a picture of a tiny spinning ball.',
 q2density:'The circle encloses every allowed state in this slice. A point on its edge is pure. The cross for the example in Understand falls outside the circle because one of its chances would be negative.',
 q2pair:'The bars count paired results. Change only the phase. The bars change, but the first partner’s matrix below them stays the same. The matrix tells you about measurements on that partner alone.',
 q2levels:'Play to follow the chance of finding state 1. An energy mismatch (detuning) limits how high the chance can rise. The example peaks at 64%.',
 q3weak:'The solid curve is exact for this two-state model. The dashed estimate agrees near zero coupling and becomes less reliable as coupling grows.',
 q3trial:'The total curve adds motion energy and potential energy. Its lowest point is the best width in this chosen trial family, not proof of an exact ground state.',
 q3scatter:'Read the angle across. More height means stronger scattering into that direction. The vertical scale changes with the settings.',
};
